Lemma slow c (IH : forall fx R c', c < c' < e -> vconst R S e -> getr R (reg 10) = Z_to_bv 64 c' -> goal_from c' fx R 0x39474) fx R d0 :
  p <= c -> c <= d0 < e -> vconst R S e -> getr R (reg 10) = Z_to_bv 64 d0 -> getr R (reg 21) = Z_to_bv 64 (sx8u (bat l (d0 - p))) ->
  goal_from d0 fx R 0x394f8.
Proof.
  intros Hpc Hd V R10 R21. pose proof V as (C2 & C5 & C6 & C7 & C8 & C9 & C12 & C13 & C14 & C15 & C16 & C17 & C18 & C19 & C20 & C28 & C29 & C30 & C31).
  destruct (byte_at d0 (d0 - p) ltac:(lia) ltac:(lia)) as (b0 & Eb0 & Hb0 & U0). rewrite <- Eb0 in R21.
  pose proof (sx8u_range b0 Hb0) as Hs5.
  LeanFeed.pfeed ident:(P) (PECVALSRP.vgS1_conc fx R M (fun j => match j with 2%nat => S | 33%nat => d0 | 35%nat => e - d0 | 36%nat => sx8u b0 | _ => 0 end)) ltac:(first [ PMK.sc ]).
  destruct P as (fx1 & R1 & M1 & _ & FR & _ & MS1 & KS1 & A11 & A23). assert (EM : M1 = M) by (apply functional_extensionality; exact FR). subst M1.
  rewrite (sx8u_land b0 Hb0) in A11, A23. rewrite Z.mod_small in A11 by lia.
  destruct (table_ok b0 Hb0) as (tb & TB & TV).
  assert (L1 : (24%bv : bv 5) <> 0%bv) by discriminate.
  assert (L2 : getr R1 (11%bv : bv 5) = Z_to_bv 64 (b0 + 80513)) by (rewrite <- A11; symmetry; apply Z_to_bv_bv_unsigned).
  assert (L3 : rdn RSEGS M (Z_to_bv 64 (b0 + 80513 + bv_signed (0%bv : bv 12))) 1 = Some [tb]).
  { change (bv_signed (0%bv : bv 12)) with 0. rewrite Z.add_0_r, Z.add_comm. rewrite (PMCG.rdn_img RSEGS M 65536 758952 _ 1 RO) by lia. exact TB. }
  pose proof (PMCG.lbu_img_run RSEGS fx1 R1 M 0x39500 W_394a8 24%bv 11%bv 0%bv (b0 + 80513) tb F_394a8 eq_refl D_394a8 L1 ltac:(lia) ltac:(lia) L2 ltac:(lia)
                ltac:(change (bv_signed (0%bv : bv 12)) with 0; lia) L3) as MSl.
  set (R2 := regupd R1 24%bv (Z_to_bv 64 (bv_unsigned tb))) in MSl.
  assert (RU : forall k, k <> 24%nat -> (k < 32)%nat -> getr R2 (PMK.reg k) = getr R1 (PMK.reg k)).
  { intros k Hk Hk32. unfold R2. replace (24%bv : bv 5) with (PMK.reg 24) by (apply bv_eq; reflexivity). apply PMPX.regupd_other_idx; lia. }
  assert (R24 : getr R2 (PMK.reg 24) = Z_to_bv 64 (bv_unsigned tb)).
  { unfold R2. replace (24%bv : bv 5) with (PMK.reg 24) by (apply bv_eq; reflexivity). apply PMPX.regupd_same_idx. lia. }
  rewrite TV in R24.
  assert (V2 : vconst R2 S e).
  { apply (vconst_keep R R2 S e V). intros k Hk. rewrite RU; [apply KS1; revert k Hk; kin| |]; unfold VC in Hk; cbn in Hk; repeat (destruct Hk as [<-|Hk]; [lia|]); destruct Hk. }
  assert (R2_10 : getr R2 (PMK.reg 10) = Z_to_bv 64 d0) by (rewrite RU by lia; rewrite (KS1 10%nat) by PMK.inl; exact R10).
  assert (R2_21 : getr R2 (PMK.reg 21) = Z_to_bv 64 (sx8u b0)) by (rewrite RU by lia; rewrite (KS1 21%nat) by PMK.inl; exact R21).
  assert (R2_23 : getr R2 (PMK.reg 23) = Z_to_bv 64 b0) by (rewrite RU by lia; rewrite <- A23; symmetry; apply Z_to_bv_bv_unsigned).
  apply (goal_pre d0 fx R 0x394f8 fx1 R2 (0x39500 + 4)).
  { eapply msteps_trans; [exact MS1| exact MSl]. }
  { intros k Hk. rewrite RU; [apply KS1; revert k Hk; kin| |]; unfold KL in Hk; cbn in Hk; repeat (destruct Hk as [<-|Hk]; [lia|]); destruct Hk. }
  change (0x39500 + 4) with 0x39504.
  clear MS1 MSl KS1 A11 A23 L1 L2 L3 TB TV.
  pose proof V2 as (D2 & D5 & D6 & D7 & D8 & D9 & D12 & D13 & D14 & D15 & D16 & D17 & D18 & D19 & D20 & D28 & D29 & D30 & D31).
  remember (utf8_trail b0) as t eqn:Tt. pose proof (utf8_trail_range b0) as TR. rewrite <- Tt in TR.
  assert (CASES : t = 0 \/ t = 1 \/ t = 2 \/ t = 3 \/ 4 <= t) by lia.
  Local Ltac vfeed P := PMK.feed P ltac:(first [ PMK.sc | exact RO ]).
  (* [comment removed for export] *)
  Local Ltac leaf d0 c IH V2 :=
    lazymatch goal with
    | H : msteps _ _ (@mkst ?fx2 ?R2 (Z_to_bv 64 0x395cc) _ _) /\ _ |- _ =>
        let MS := fresh "MS" in let KS := fresh "KS" in
        split_exit H MS KS; raws;
        apply (goal_pre d0 _ _ _ fx2 R2 _ MS ltac:(intros k Hk; apply KS; revert k Hk; kin));
        let A := get_reg R2 11%nat in
        apply (goal_err d0 fx2 R2 _ ltac:(rewrite (KS 2%nat) by PMK.inl; exact (proj1 V2)) A); [clear - A; lia|];
        first [ apply (valid_short_bt l (d0 - p) _ _ ltac:(lia) ltac:(eassumption) ltac:(eassumption)); lia
              | apply (valid_bad_bt l (d0 - p) _ _ ltac:(lia) ltac:(eassumption) ltac:(eassumption)); [lia|];
                lazymatch goal with E : ?tv = utf8_trail _ |- context [Z.to_nat (?tv + 1)] =>
                  first [ replace (tv + 1) with 1 by lia; change (Z.to_nat 1) with 1%nat; rewrite firstn_skipn_1 by lia
                        | replace (tv + 1) with 2 by lia; change (Z.to_nat 2) with 2%nat; rewrite firstn_skipn_2 by lia
                        | replace (tv + 1) with 3 by lia; change (Z.to_nat 3) with 3%nat; rewrite firstn_skipn_3 by lia
                        | replace (tv + 1) with 4 by lia; change (Z.to_nat 4) with 4%nat; rewrite firstn_skipn_4 by lia
                        | rewrite legal_long; [reflexivity| rewrite length_firstn, length_skipn; unfold blen in *; lia] ] end;
                fold_bytes; legal_false
              | exfalso; lia ]
    | H : msteps _ _ (@mkst ?fx2 ?R2 (Z_to_bv 64 0x395a4) _ _) /\ _ |- _ =>
        let MS := fresh "MS" in let KS := fresh "KS" in
        split_exit H MS KS; raws;
        apply (goal_pre d0 _ _ _ fx2 R2 _ MS ltac:(intros k Hk; apply KS; revert k Hk; kin));
        let A := get_reg R2 22%nat in
        lazymatch type of A with getr _ _ = Z_to_bv 64 ?cv =>
          apply (goal_same d0 cv);
          [ first [ rewrite (valid_step_bt l (d0 - p) _ _ (cv - p) ltac:(lia) ltac:(eassumption) ltac:(eassumption)); [reflexivity| lia| lia|];
                    lazymatch goal with E : ?tv = utf8_trail _ |- context [Z.to_nat (?tv + 1)] =>
                      first [ replace (tv + 1) with 1 by lia; change (Z.to_nat 1) with 1%nat; rewrite firstn_skipn_1 by lia
                            | replace (tv + 1) with 2 by lia; change (Z.to_nat 2) with 2%nat; rewrite firstn_skipn_2 by lia
                            | replace (tv + 1) with 3 by lia; change (Z.to_nat 3) with 3%nat; rewrite firstn_skipn_3 by lia
                            | replace (tv + 1) with 4 by lia; change (Z.to_nat 4) with 4%nat; rewrite firstn_skipn_4 by lia ] end;
                    fold_bytes; legal_true
                  | exfalso; lia ]
          | apply (join_case c IH fx2 R2 cv ltac:(lia) ltac:(lia) (vconst_keep _ R2 S e V2 ltac:(intros k Hk; apply KS; revert k Hk; kin)) A) ]
        end
    end.
  Local Ltac leaves d0 c IH V2 := repeat (lazymatch goal with H : _ \/ _ |- _ => destruct H as [H|H]; [leaf d0 c IH V2|] end); leaf d0 c IH V2.
  destruct CASES as [Et|[Et|[Et|[Et|Et]]]].
  - rewrite Et in R24. pose proof (trail_0 b0 ltac:(rewrite <- Tt; exact Et)) as Tc.
    LeanFeed.pfeed ident:(P) (PECVALSRP.vgS2_0_conc fx1 R2 M (fun j => match j with 2%nat => S | 33%nat => d0 | 35%nat => e - d0 | 36%nat => sx8u b0 | 37%nat => b0 | _ => 0 end)) ltac:(first [ PMK.sc | exact RO ]).
    destruct P as (fx2 & R3 & M3 & _ & FR3 & _ & EX). assert (EM : M3 = M) by (apply functional_extensionality; exact FR3). subst M3.
    leaves d0 c IH V2.
  - rewrite Et in R24. pose proof (trail_1 b0 ltac:(rewrite <- Tt; exact Et)) as Tc. destruct (Z_le_gt_dec (e - d0) 1) as [LE|GT].
    + LeanFeed.pfeed ident:(P) (PECVALSRP.vgS2_1a_conc fx1 R2 M (fun j => match j with 2%nat => S | 33%nat => d0 | 35%nat => e - d0 | 36%nat => sx8u b0 | 37%nat => b0 | _ => 0 end)) ltac:(first [ PMK.sc | exact RO ]).
      destruct P as (fx2 & R3 & M3 & _ & FR3 & _ & EX). assert (EM : M3 = M) by (apply functional_extensionality; exact FR3). subst M3.
      leaf d0 c IH V2.
    + destruct (byte_at (d0 + 1) (d0 - p + 1) ltac:(lia) ltac:(lia)) as (b1 & Eb1 & Hb1 & U1).
      LeanFeed.pfeed ident:(P) (PECVALSRP.vgS2_1b_conc fx1 R2 M (fun j => match j with 2%nat => S | 33%nat => d0 | 35%nat => e - d0 | 36%nat => sx8u b0 | 37%nat => b0
                                                   | 39%nat => b1 | _ => 0 end)) ltac:(first [ PMK.sc | exact RO ]).
      destruct P as (fx2 & R3 & M3 & _ & FR3 & _ & EX). assert (EM : M3 = M) by (apply functional_extensionality; exact FR3). subst M3.
      leaves d0 c IH V2.
  - rewrite Et in R24. pose proof (trail_2 b0 ltac:(rewrite <- Tt; exact Et)) as Tc. destruct (Z_le_gt_dec (e - d0) 2) as [LE|GT].
    + LeanFeed.pfeed ident:(P) (PECVALSRP.vgS2_2a_conc fx1 R2 M (fun j => match j with 2%nat => S | 33%nat => d0 | 35%nat => e - d0 | 36%nat => sx8u b0 | 37%nat => b0 | _ => 0 end)) ltac:(first [ PMK.sc | exact RO ]).
      destruct P as (fx2 & R3 & M3 & _ & FR3 & _ & EX). assert (EM : M3 = M) by (apply functional_extensionality; exact FR3). subst M3.
      leaf d0 c IH V2.
    + destruct (byte_at (d0 + 1) (d0 - p + 1) ltac:(lia) ltac:(lia)) as (b1 & Eb1 & Hb1 & U1).
      destruct (byte_at (d0 + 2) (d0 - p + 2) ltac:(lia) ltac:(lia)) as (b2 & Eb2 & Hb2 & U2).
      LeanFeed.pfeed ident:(P) (PECVALSRP.vgS2_2b_conc fx1 R2 M (fun j => match j with 2%nat => S | 33%nat => d0 | 35%nat => e - d0 | 36%nat => sx8u b0 | 37%nat => b0
