      LeanFeed.pfeed ident:(P) (PECVALSRP.vgS2_3b_conc fx1 R2 M (fun j => match j with 2%nat => S | 33%nat => d0 | 35%nat => e - d0 | 36%nat => sx8u b0 | 37%nat => b0
